\section{Proof of Theorem~\ref{thm:sufficient}}
\label{app:proof}

We prove that the G-MFRM is locally identifiable under the conditions of Theorem~\ref{thm:sufficient}. Following \citet{rothenberg1971}, a parametric model is locally identifiable at the true parameter vector $\boldsymbol{\psi}_0$ if and only if the Fisher information matrix $\mathbf{F}(\boldsymbol{\psi}_0)$ is non-singular.

\paragraph{Setup.} The G-MFRM parameter vector is $\boldsymbol{\psi} = (\boldsymbol{\theta}, \mathbf{c}, \mathbf{b}, \mathbf{d}, \boldsymbol{\tau})$, where $\boldsymbol{\theta} \in \mathbb{R}^{N-1}$ (after the location constraint $\sum_n \theta_n = 0$), $\mathbf{c} \in \mathbb{R}_{\geq 0}^N$, $\mathbf{b} \in \mathbb{R}^I$, $\mathbf{d} \in \mathbb{R}^J$, and $\boldsymbol{\tau} \in \mathbb{R}^{K-1}$. The exposure vector $\mathbf{e} = (e_1, \ldots, e_I)$ is fixed externally and treated as known. The linear predictor is $\eta_{nijk} = \theta_n - b_i - d_j - \tau_k + c_n \cdot e_i$, with partial derivatives:
%
\begin{equation*}
\frac{\partial \eta_{nijk}}{\partial \theta_n} = 1, \quad
\frac{\partial \eta_{nijk}}{\partial c_n} = e_i, \quad
\frac{\partial \eta_{nijk}}{\partial b_i} = -1, \quad
\frac{\partial \eta_{nijk}}{\partial d_j} = -1, \quad
\frac{\partial \eta_{nijk}}{\partial \tau_k} = -1.
\end{equation*}

\paragraph{Fisher information weights.} For each observation cell $(n,i,j)$, the Fisher information weight under the cumulative logit model is
%
\begin{equation}
\label{eq:fisher_weight}
w_{nij} = \sum_{k=1}^{K} \frac{\bigl[\sigma'(\eta_{nijk}) - \sigma'(\eta_{nij,k+1})\bigr]^2}{P(Y_{nij} = k)},
\end{equation}
%
where $\sigma(x) = (1 + e^{-x})^{-1}$, $\sigma'(x) = \sigma(x)(1 - \sigma(x))$, and we set $\sigma'(\eta_{nij,0}) = \sigma'(\eta_{nij,K+1}) = 0$ at the boundaries. Since $P(Y_{nij} = k) > 0$ for all categories and $\sigma'(\cdot) > 0$, we have $w_{nij} > 0$ for all $(n,i,j)$.

\paragraph{Step 1: The $(\theta_n, c_n)$ submatrix.} For each model $n$, the $2 \times 2$ Fisher information submatrix is
%
\begin{equation}
\label{eq:fisher_block}
\mathbf{F}_n = \sum_{i=1}^{I} \sum_{j=1}^{J} w_{nij}
\begin{pmatrix} 1 & e_i \\ e_i & e_i^2 \end{pmatrix}.
\end{equation}
%
Its determinant is
%
\begin{equation}
\det \mathbf{F}_n = \Bigl(\textstyle\sum_{i,j} w_{nij}\Bigr)\Bigl(\textstyle\sum_{i,j} w_{nij}\, e_i^2\Bigr) - \Bigl(\textstyle\sum_{i,j} w_{nij}\, e_i\Bigr)^2 = W_n^2 \cdot \mathrm{Var}_w(e_i),
\end{equation}
%
where $W_n = \sum_{i,j} w_{nij}$ and $\mathrm{Var}_w(e_i) = \overline{e^2}_n - \bar{e}_n^2$ is the weighted variance of exposure with weights $w_{nij}$. By the Cauchy--Schwarz inequality, $\mathrm{Var}_w(e_i) \geq 0$, with equality if and only if $e_i$ is constant across all items with $w_{nij} > 0$. Under condition~(iii), $e_i$ takes at least two distinct values, and under condition~(i) (fully crossed), all items are observed for each model, so $w_{nij} > 0$ for all $(i,j)$. Therefore $\det \mathbf{F}_n > 0$ and each $\mathbf{F}_n$ is positive definite.

